import Image from "next/image";
import { cn } from "@/lib/utils/cn";

/**
 * Dukhata logo — the owner's mark, drawn as "outline + soft fill".
 *
 * `/logo-mark.png` is a contour stroke traced on the boundary of the owner's
 * artwork, with a whisper of the same ink inside it. It is deliberately NOT the
 * app icon: the icon stays the owner's original lime-on-black artwork, while
 * every in-page placement uses this ink outline so it belongs on the paper page.
 *
 * Generated by `scripts/generate_icons.py`, from the same source as the icons,
 * so the mark and the icon can never drift apart.
 *
 * The lockup is forced LTR so the Latin brand never re-orders inside an RTL
 * document.
 */
export function Logo({
  className,
  showWordmark = true,
  priority = false,
}: {
  className?: string;
  showWordmark?: boolean;
  /** Set on the first above-the-fold instance to avoid a layout flash. */
  priority?: boolean;
}) {
  return (
    <span dir="ltr" className={cn("inline-flex items-center gap-2", className)}>
      <Image
        src="/logo-mark.png"
        alt=""
        width={256}
        height={256}
        priority={priority}
        className="h-7 w-7 shrink-0 drop-shadow-[0_1px_2px_rgba(28,25,23,0.22)]"
      />
      {showWordmark && (
        <span className="font-display text-[1.0625rem] font-semibold tracking-[-0.02em] text-ink">
          Dukhata
        </span>
      )}
    </span>
  );
}
